#!/usr/bin/env bash
# Offline notice generation. --check verifies pins and generated files;
# --validate --manifest PATH validates a candidate manifest without writing.
set -euo pipefail
root=$(cd "$(dirname "$0")/.." && pwd)
exec python3 - "$root" "$@" <<'PY'
import argparse, html, json, pathlib, re, subprocess, sys
root=pathlib.Path(sys.argv[1])
p=argparse.ArgumentParser()
p.add_argument('--check',action='store_true')
p.add_argument('--validate',action='store_true')
p.add_argument('--manifest',type=pathlib.Path,default=root/'docs/third-party.json')
a=p.parse_args(sys.argv[2:])
engine=(root/'LICENSE').is_file() and not (root/'app/Package.swift').is_file()
def read(path):
    f=root/path
    if f.is_file(): return f.read_text()
    # Sparse worktrees still validate against their own committed source, offline.
    return subprocess.check_output(['git','show','HEAD:'+path],cwd=root,text=True,stderr=subprocess.DEVNULL)
try:
    components=json.loads(a.manifest.read_text())['components']
    by={c['id']:c for c in components}
    if len(by)!=len(components): raise ValueError('duplicate component ID')
    expected={}
    locks=['Package.resolved'] if engine else ['Package.resolved', 'app/Package.resolved']
    for lock in locks:
        for pin in json.loads(read(lock))['pins']:
            name, version = pin['identity'], pin['state']['version']
            if name in expected and expected[name]!=version: raise ValueError('conflicting source pins: '+name)
            expected[name]=version
            if by.get(name,{}).get('source','').removesuffix('.git')!=pin['location'].removesuffix('.git'):
                raise ValueError('source mismatch: '+name)
    if not engine:
        web_lock = read('website/bun.lock')
        for name in json.loads(read('website/package.json')).get('dependencies', {}):
            match = re.search(r'"'+re.escape(name)+r'":\s*\["'+re.escape(name)+r'@([^"\n]+)"', web_lock)
            if not match: raise ValueError('website lock pin not found: '+name)
            expected['website/'+name] = match.group(1)
    for name,version in re.findall(r'^\s+(\S+) (v\S+)',read('tools/buildkit-adapter/go.mod'),re.M): expected[name]=version
    for path, constructor in [('Sources/NoodleCore/Tools/ToolPins.swift','ToolPin'), ('Sources/noodle/Commands/Scan/ScanTools.swift','ScanTool')]:
        pins=re.findall(constructor+r'\(\s*name:\s*"([^"\n]+)"\s*,\s*version:\s*"([^"\n]+)"',read(path))
        if not pins: raise ValueError('no tool pins found: '+path)
        for name,version in pins:
            if name in expected and expected[name]!=version: raise ValueError('conflicting source pins: '+name)
            expected[name]=version
    # Explicit required identities prevent deleting a component and its rule together.
    required={'linux','e2fsprogs','tini','docker','docker-compose','docker-buildx','grype','syft','cloudflared','swiftterm','mlx-serve','mlx-serve/llama.cpp','mlx-serve/apache-2.0-notice','actions-runner'}
    if engine: required.remove('swiftterm')
    missing=(required|set(expected))-set(by)
    if missing: raise ValueError('missing components: '+', '.join(sorted(missing)))
    for c in components:
        for key in ('id','license','source','use'):
            if not c.get(key): raise ValueError('missing '+key+' for '+c.get('id','?'))
        pin=c.get('pin',{})
        if c['id'] in required-{'swiftterm'} and pin.get('kind')!='regex': raise ValueError('missing pin rule: '+c['id'])
        if pin.get('kind')=='regex':
            match=re.search(pin['pattern'],read(pin['path']),re.M)
            if not match: raise ValueError('pin not found: '+c['id'])
            version=match.group(1)
            if c['id'] in expected and expected[c['id']]!=version: raise ValueError('conflicting source pins: '+c['id'])
            expected[c['id']]=version
    # Every pinned model revision in the catalog needs a component.
    versions={c['version'] for c in components}
    for rev in re.findall(r'\b[a-f0-9]{40}\b',read('Sources/noodle/Commands/Models/ModelCatalog.swift')):
        if rev not in versions: raise ValueError('catalog model missing from manifest: '+rev)
    for name,version in expected.items():
        if by[name]['version']!=version: raise ValueError('version drift: '+name+' (source '+version+', manifest '+str(by[name]['version'])+')')
    # Newly linked Swift packages and Go modules are covered by the full inventories above.
    if a.validate:
        print('Third-party manifest pins verified.'); sys.exit(0)
    notice='Noodle engine\nCopyright 2026 Ansuman Shah.\nLicensed under Apache-2.0; third-party components retain their own licences.\n\nGenerated by scripts/gen-notice.sh from docs/third-party.json.\n\n' if engine else 'Noodle\nCopyright 2026 Ansuman Shah\n\nLicensed under the Apache License, Version 2.0. See LICENSE.\n\nNoodle includes, links to or downloads the third-party software listed below.\nEach component stays under its own licence. Licence texts that must travel\nwith the software follow the list. Licence texts for the modules linked into\nthe BuildKit adapter are in BuildKitAdapter-Licenses.txt in the application\nresources. e2fsprogs ships with its upstream NOTICE, and its source archive is\npublished with each release.\n\n'
    rows=[]
    for c in components:
        version=c['version'] or 'Not pinned / not currently linked'
        note=f"Note: {c['note']}\n" if c.get('note') else ''
        notice+=f"{c['id']} {version}\nLicence: {c['license']}\nSource: {c['source']}\nUse: {c['use']}\n{note}\n"
        vals=[c['id'],version,c['use'],c['license']]
        rows.append('<tr>'+''.join('<td>'+html.escape(v)+'</td>' for v in vals)+'<td><a href="'+html.escape(c['source'],quote=True)+'">Source</a></td></tr>')
    start='<!-- BEGIN GENERATED THIRD-PARTY -->'; end='<!-- END GENERATED THIRD-PARTY -->'
    table=start+'\n<div class="tw"><table class="stack"><thead><tr><th>Component</th><th>Version</th><th>Used for</th><th>Licence</th><th>Source</th></tr></thead><tbody>\n'+'\n'.join(rows)+'\n</tbody></table></div>\n'+end
    # Hand-kept attribution and licence texts, not derived from the manifest.
    notice=notice.rstrip()+'\n\n'+(root/'docs/notice-extra.txt').read_text()
    outputs=[('NOTICE',notice)]
    # website/ renders the same table from a fragment and serves the same notice text.
    if not engine: outputs+=[('website/src/generated/third-party-table.html',table+'\n'),('website/public/THIRD_PARTY_NOTICES.txt',notice)]
    for path,content in outputs:
        f=root/path
        if a.check:
            if f.read_text()!=content: raise ValueError('stale generated file: '+path+'; run scripts/gen-notice.sh')
        else: f.write_text(content)
    print('Third-party notices '+('verified.' if a.check else 'generated.'))
except (ValueError,KeyError,OSError,subprocess.CalledProcessError) as error:
    print('gen-notice: '+str(error),file=sys.stderr);sys.exit(1)
PY
